 private LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);return l;}
 private void render(){Ui.chip(all,!favoriteTab);Ui.chip(favorites,favoriteTab);shown.clear();List<RadioStation> stored=RadioStore.favorites(this);favoriteIds.clear();for(RadioStation saved:stored)favoriteIds.add(saved.id);String q=SearchText.normalize(query.getText());for(RadioStation s:favoriteTab?stored:catalog)if(!favoriteTab||SearchText.normalize(s.name+" "+s.country).contains(q))shown.add(s);adapter.notifyDataSetChanged();status.setText(shown.isEmpty()?(favoriteTab?"Nenhuma rádio favorita nesta busca. Use o coração de uma emissora ou adicione seu link HTTPS.":"Busque uma emissora ou adicione um link HTTPS."):shown.size()+(favoriteTab?" rádios favoritas":" emissoras • toque para ouvir"));}
 private void search(){((android.view.inputmethod.InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(query.getWindowToken(),0);query.clearFocus();if(favoriteTab){render();return;}initialized=true;int token=++generation;if(task!=null)task.cancel(true);java.net.HttpURLConnection old=active;if(old!=null)old.disconnect();search.setEnabled(false);status.setText("Consultando rádios…");String term=query.getText().toString().trim();boolean brazil=region.getSelectedItemPosition()==0;task=worker.submit(()->{try{List<RadioStation> found=RadioDirectory.search(term,brazil,c->active=c);handler.post(()->{if(isDestroyed()||!started||token!=generation)return;catalog=found;RadioStore.cache(this,found,term,brazil);search.setEnabled(true);render();if(found.isEmpty())status.setText("Nenhuma transmissão HTTPS encontrada. Tente outro nome ou selecione Todos os países.");});}catch(Exception e){handler.post(()->{if(isDestroyed()||!started||token!=generation)return;search.setEnabled(true);status.setText("Não foi possível consultar o catálogo agora. Suas rádios salvas continuam disponíveis.");});}});}
 private void play(RadioStation station){if(player==null){pending=station;status.setText("Conectando ao tocador…");return;}if(player.getCurrentMediaItem()!=null&&player.getCurrentMediaItem().mediaId.equals("radio:"+station.id)&&player.getPlayWhenReady()&&player.getPlaybackState()!=Player.STATE_IDLE&&player.getPlaybackState()!=Player.STATE_ENDED){updatePlayer();return;}player.setMediaItem(RadioMedia.item(station));player.prepare();player.play();status.setText("Conectando a "+station.name+"…");updatePlayer();adapter.notifyDataSetChanged();}
