 @Override protected void onStart(){super.onStart();started=true;if(query!=null){render();updatePlayer();if(!initialized&&!favoriteTab)search();}}
 @Override protected void onStop(){started=false;generation++;if(task!=null)task.cancel(true);java.net.HttpURLConnection old=active;if(old!=null)old.disconnect();if(search!=null)search.setEnabled(true);super.onStop();}
